import Image from 'next/image';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Button } from '@/components/ui/button';
import { campaigns } from '@/lib/data';
import Link from 'next/link';

export default function CampaignsPage() {
  return (
    <div>
      <h1 className="text-3xl font-bold mb-6 font-headline">Our Campaigns</h1>
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {campaigns.map((campaign) => {
          const progress = (campaign.raised / campaign.goal) * 100;
          return (
            <Card key={campaign.id} className="flex flex-col">
              <CardHeader>
                <div className="aspect-video relative mb-4">
                    <Image
                      src={campaign.imageUrl}
                      alt={campaign.title}
                      fill
                      className="rounded-lg object-cover"
                      data-ai-hint={campaign.imageHint}
                    />
                </div>
                <CardTitle className="font-headline">{campaign.title}</CardTitle>
                <CardDescription>{campaign.description}</CardDescription>
              </CardHeader>
              <CardContent className="flex-grow">
                <div className="mb-2 flex justify-between text-sm">
                  <span>Raised: ${campaign.raised.toLocaleString()}</span>
                  <span className="font-semibold">Goal: ${campaign.goal.toLocaleString()}</span>
                </div>
                <Progress value={progress} />
              </CardContent>
              <CardFooter>
                <Button asChild className="w-full">
                  <Link href="/donate">Donate to this Campaign</Link>
                </Button>
              </CardFooter>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
